<template>
  <div class="app-container agent-page">
    <div class="page-heading"><div><h2>评估中心</h2><p>查看确定性评估评分、交付完整度、降级产物和未计价调用。</p></div><el-tag type="info" effect="plain">确定性评估</el-tag></div>
    <el-row :gutter="14" class="summary-row"><el-col :xs="12" :sm="8" :lg="4" v-for="item in cards" :key="item.key"><el-card shadow="never" class="summary-card"><div class="summary-label">{{ item.label }}</div><div class="summary-value" :class="item.tone">{{ item.value }}</div></el-card></el-col></el-row>
    <el-select v-if="tenantScopes.length" v-model="query.tenantKey" placeholder="授权租户" clearable style="width: 190px; margin-bottom: 8px" @change="load"><el-option v-for="scope in tenantScopes" :key="scope.tenantKey" :label="scope.tenantKey" :value="scope.tenantKey" /></el-select><el-input v-else v-model="query.tenantKey" placeholder="租户 Key（回车后点击刷新）" clearable style="width: 180px; margin-bottom: 8px" @keyup.enter="load" />
    <el-card shadow="never"><el-form :inline="true" class="toolbar"><el-form-item><el-select v-model="query.taskType" placeholder="任务类型" clearable style="width: 180px" @change="load"><el-option v-for="item in taskTypes" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-select v-model="query.verdict" placeholder="评估结论" clearable style="width: 140px" @change="load"><el-option v-for="item in verdicts" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-input-number v-model="query.minimumScore" :min="0" :max="100" :step="5" controls-position="right" placeholder="最低评分" @change="load" /></el-form-item><el-form-item><el-select v-model="query.gatePassed" placeholder="门槛状态" clearable style="width: 140px" @change="load"><el-option label="门槛通过" :value="true" /><el-option label="门槛失败" :value="false" /></el-select></el-form-item><el-button type="primary" :loading="loading" @click="load">刷新</el-button></el-form><el-table v-loading="loading" :data="rows" empty-text="暂无评估记录"><el-table-column prop="taskKey" label="任务" min-width="180" /><el-table-column prop="taskType" label="类型" width="160" /><el-table-column prop="taskStatus" label="任务状态" width="140" /><el-table-column prop="score" label="评分" width="90" /><el-table-column prop="minimumEvaluationScore" label="门槛" width="90" /><el-table-column label="门槛结果" width="110"><template #default="{ row }"><el-tag :type="row.evaluationGatePassed === true ? 'success' : row.evaluationGatePassed === false ? 'danger' : 'info'">{{ row.evaluationGatePassed === true ? '通过' : row.evaluationGatePassed === false ? '失败' : '-' }}</el-tag></template></el-table-column><el-table-column label="结论" width="100"><template #default="{ row }"><el-tag :type="verdictType(row.verdict)">{{ row.verdict || '-' }}</el-tag></template></el-table-column><el-table-column label="步骤成功率" width="130"><template #default="{ row }">{{ percent(row.stepSuccessRate) }}</template></el-table-column><el-table-column label="产物就绪率" width="130"><template #default="{ row }">{{ percent(row.artifactReadyRate) }}</template></el-table-column><el-table-column prop="degradedArtifacts" label="降级产物" width="110" /><el-table-column prop="unpricedCalls" label="未计价调用" width="120" /><el-table-column prop="createdAt" label="评估时间" width="180" /></el-table><pagination v-show="total > 0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" /></el-card>
  </div>
</template>
<script setup name="JgAgentEvaluation">
import { getAgentEvaluation, listMyAgentTenantScopes } from '@/api/jiugai/agentConfig'
const loading = ref(false); const rows = ref([]); const total = ref(0); const summary = ref({}); const query = reactive({ pageNum: 1, pageSize: 20, taskType: undefined, verdict: undefined, minimumScore: undefined, gatePassed: undefined, tenantKey: undefined }); const tenantScopes = ref([]); const taskTypes = ['CONTENT_CREATION', 'GENERAL', 'OPERATIONS_REVIEW', 'DSH_SESSION', 'DSH_BROWSER', 'DSH_DEVOPS_BUILD', 'DSH_DEVOPS_RELEASE', 'DSH_DEVOPS_ROLLBACK', 'DSH_PLATFORM_AUDIT']; const verdicts = ['PASS', 'WARN', 'FAIL']
const cards = computed(() => [{ key: 'evaluationCount', label: '评估数', value: summary.value.evaluationCount || 0 }, { key: 'averageScore', label: '平均评分', value: Number(summary.value.averageScore || 0).toFixed(1) }, { key: 'passCount', label: 'PASS', value: summary.value.passCount || 0 }, { key: 'warnCount', label: 'WARN', value: summary.value.warnCount || 0, tone: 'warning' }, { key: 'failCount', label: 'FAIL', value: summary.value.failCount || 0, tone: 'danger' }, { key: 'gatePassedCount', label: '门槛通过', value: summary.value.gatePassedCount || 0 }])
function percent(value) { const number = Number(value || 0); return `${(Number.isFinite(number) ? number * 100 : 0).toFixed(1)}%` }
function verdictType(value) { return value === 'PASS' ? 'success' : value === 'WARN' ? 'warning' : 'danger' }
async function load() { loading.value = true; try { const response = await getAgentEvaluation(query); const data = response.data || {}; summary.value = data.summary || {}; rows.value = data.rows || []; total.value = data.total || 0 } finally { loading.value = false } }
async function loadTenantScopes() { try { const response = await listMyAgentTenantScopes(); tenantScopes.value = Array.isArray(response) ? response : (response.data || []); if (tenantScopes.value.length && !query.tenantKey) query.tenantKey = tenantScopes.value[0].tenantKey } catch (e) { tenantScopes.value = [] } }
onMounted(async () => { await loadTenantScopes(); await load() })
</script>
<style scoped>
.agent-page { color: #1f2937; }.page-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }.page-heading h2 { margin: 0 0 6px; font-size: 22px; }.page-heading p { margin: 0; color: #6b7280; }.summary-row { margin-bottom: 14px; }.summary-card { min-height: 92px; }.summary-label { color: #6b7280; font-size: 13px; }.summary-value { margin-top: 10px; color: #1f2937; font-size: 22px; font-weight: 600; }.summary-value.warning { color: #d97706; }.summary-value.danger { color: #dc2626; }.toolbar { margin-bottom: 6px; }
</style>
